import{experimentResult}from './el3-models.js?v=20261023-physicscomplete01';
const ink='#faf5ed',mint='#a9cabe',coral='#f38b73',dim='#aec1cb',blue='#91b8e5';
const esc=x=>String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const fmt=x=>Number(Number(x).toFixed(3));
const T=(x,y,s,n=18,c=ink)=>`<text x="${x}" y="${y}" text-anchor="middle" fill="${c}" font-family="sans-serif" font-size="${n}">${esc(s)}</text>`;
const L=(x,y,u,v,c=dim,w=3)=>`<path d="M${x} ${y}L${u} ${v}" fill="none" stroke="${c}" stroke-width="${w}"/>`;
const B=(x,y,w,h,c='#264757')=>`<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="12" fill="${c}" stroke="${dim}"/>`;
const dot=(x,y,c=coral)=>`<circle cx="${x}" cy="${y}" r="7" fill="${c}"/>`;
export const domesticSVG=(body,label)=>`<svg viewBox="0 0 560 480" role="img" aria-label="${esc(label)}">${body}</svg>`;
export function waveform({a='ac',b='50',progress=.25,movie=false,revealed=true}={}){let ac=a==='ac',freq=+b,cycles=ac?freq:0,path='';for(let j=0;j<=200;j++){let x=65+j*2.15,y=ac?227-88*Math.sin(4*Math.PI*j/200):160;path+=(j?'L':'M')+x+' '+y;}let x=65+430*progress,y=ac?227-88*Math.sin(4*Math.PI*progress):160;
let body=T(280,30,ac?'Alternating polarity':'One polarity · direct potential difference',23)+L(65,103,65,340)+L(65,227,510,227)+T(30,122,'+',22)+T(30,233,'0',17)+T(30,327,'−',22)+T(280,87,'Potential difference / normalised scale',17)+`<path d="${path}" fill="none" stroke="${ac?coral:mint}" stroke-width="4"/>`+dot(x,y)+L(x,340,x,y,dim,1)+T(65,365,'0',15)+T(280,365,ac?fmt(1000/freq)+' ms':'',15)+T(495,365,ac?fmt(2000/freq)+' ms':'Time →',15)+T(280,397,ac?'Two full cycles shown · time / ms':'Time axis · DC remains positive',18)+T(280,433,revealed?cycles+' complete AC cycles in 1 s':'Predict complete AC cycles in 1 s',20)+T(280,466,'Playback slowed · normalised height is not 230 V peak',14);
if(movie)body+=T(280,59,ac?(Math.sin(4*Math.PI*progress)>=0?'Positive half-cycle':'Negative half-cycle'):'DC does not reverse',17,mint);
return domesticSVG(body,`${ac?'AC reverses polarity':'DC keeps one polarity'}. ${revealed?cycles+' complete AC cycles per second.':'Cycle count concealed until reveal.'} Normalised graph; time expanded, not real-time mains. Two AC cycles fill the time axis.`);}
export function mainsFigure({a='live',b='earth',progress=0,movie=false,revealed=true}={}){let stage=movie?Math.min(2,Math.floor(progress*3)):0,fault=stage===1,cut=stage===2;let body=T(280,28,'An earthed appliance · conceptual connections',22)+B(260,118,245,234)+T(382,150,'Metal case',19)+B(326,182,125,72)+T(388,225,'Load',20)+T(99,93,'Three-core cable',18);
body+=`<path d="M44 185H140${cut?'m32 0':'h32'}H326" fill="none" stroke="#d0a47c" stroke-width="5"/>`+T(105,170,'L · brown',17)+B(164,174,45,21,cut?'#172e42':'#805e4c')+T(186,149,cut?'Disconnected':'Protection',14)+`<path d="M44 259H325" fill="none" stroke="${blue}" stroke-width="5"/>`+T(119,286,'N · blue',17)+`<path d="M44 325H260" fill="none" stroke="#90b995" stroke-width="7"/><path d="M44 325H260" fill="none" stroke="#eadb88" stroke-width="3" stroke-dasharray="10 9"/>`+T(128,351,'E · green/yellow',17)+dot(260,325,mint)+T(383,330,'Earth bonded to case',15);
if(fault||cut)body+=`<path d="M286 185V325H261" fill="none" stroke="${fault?coral:dim}" stroke-width="4" stroke-dasharray="8 5"/>`+T(390,303,'Live–case fault',16,coral);
if(movie&&fault)body+=dot(45+215*((progress*9)%1),325,coral);
body+=T(280,391,movie?['Normal: no earth current','Fault: protective path carries current','Protection disconnects live'][stage]:(a==='live'?'Live is about 230 V relative to '+b:'Neutral is close to earth potential'),21)+T(280,428,movie?'Sequence is symbolic; no real fault time/current':revealed?experimentResult('mains',a,b).value+' V nominal difference':'Predict nominal potential difference / V',19)+T(280,466,'Study only · no live-mains experiment or wiring instructions',14);
return domesticSVG(body,`Labelled brown live, blue neutral, striped green/yellow earth connected to metal case. ${movie?['Normal operation, earth carries no current.','Live-case fault allows protective earth current.','Protective device disconnects live; fault remains indicated.'][stage]:'Conceptual normal appliance; compare '+a+' to '+b+'.'} Protection must be suitable; fault timing and current not calculated.`);}
export function energyFigure({kind='power',a,b,progress=.5,movie=false,revealed=true}={}){let energy=kind==='appliances',A=+(a||(energy?'60':'12')),Bv=+(b||(energy?'10':'2')),P=energy?A:A*Bv,t=energy?Bv:10,E=P*t,elapsed=movie?t*progress:t;let body=T(280,29,energy?'Transfer an energy account':'Power is energy transferred each second',23)+B(45,87,170,113)+T(130,118,energy?'Battery / mains':'Electrical input',20)+T(130,155,energy?P+' W':A+' V × '+Bv+' A',22)+L(220,143,320,143,coral,4)+B(325,87,190,113)+T(420,118,energy?'Motor / heater':'Device',22)+T(420,155,revealed||movie?P+' J each second':'Predict transfer rate',19);
for(let j=0;j<3;j++)body+=dot(230+((progress+j/3)%1)*80,143,mint);
body+=T(280,244,'Elapsed time '+fmt(elapsed)+' / '+t+' s',22)+B(65,273,430,56,'#193647')+`<rect x="67" y="275" width="${426*elapsed/t}" height="52" rx="10" fill="${coral}"/>`+T(280,310,revealed||movie?fmt(P*elapsed)+' J transferred':'Predict total energy',20,'#faf5ed')+T(280,368,energy?'E = P × t':'P = V × I',23)+T(280,406,revealed?energy?P+' W × '+t+' s = '+E+' J':P+' W = '+P+' J/s':'Predict '+(energy?'energy / J':'power / W'),22)+T(280,448,'Charge is conserved · energy transferred, not used-up charge',15)+T(280,473,'Constant power · total input, not guaranteed useful output',13);
return domesticSVG(body,`${revealed||movie?P+' watts constant electrical input. '+t+' seconds transfers '+E+' joules; displayed elapsed '+fmt(elapsed)+' seconds.':'Selected input '+A+' and '+Bv+'; computed output concealed until reveal.'} Account reset repeats the example, not a real energy reversal. Input includes useful and dissipated transfers.`);}
export function gridFigure({a='100',b='1000',progress=0,movie=false,revealed=true,state='0'}={}){let V=movie?(progress<.5?100:200):+a,P=+b,r=experimentResult('grid',String(V),String(P));let body=T(280,28,'Step up → transmit → step down',24);
for(let [x,s,v]of[[15,'Station','AC supply'],[155,'Step up','Higher V'],[295,'Cable','R = 1 Ω'],[435,'Step down','Consumers']])body+=B(x,83,110,98)+T(x+55,112,s,18)+T(x+55,151,v,15);
body+=L(40,222,510,222,coral,4)+L(40,250,510,250,mint,3);if(movie)for(let j=0;j<6;j++)body+=dot(40+((progress*2+j/6)%1)*470,222);
body+=T(280,204,'Sending power '+P+' W · voltage '+V+' V',20)+T(280,291,revealed?'Current '+fmt(r.I)+' A = P / V':'Predict cable loss from I = P/V',21)+T(280,329,revealed?'Cable heating '+fmt(r.loss)+' W = I²R':'Cable R = 1 Ω · loss = I²R',21,coral)+T(280,369,revealed?'After cable '+fmt(r.received)+' W':'Sending power − cable loss',21,mint)+T(280,407,'Fixed sending power · fixed total line resistance',16)+T(280,443,'Toy voltages; not UK transmission values or transformer internals',14)+T(280,472,'Consumer voltage stepped down to about 230 V in the real system',13);
if(state==='4')body=T(280,55,'Higher · ideal transformer',25)+B(60,125,180,125)+B(320,125,180,125)+L(241,187,319,187,coral,4)+T(150,164,'Primary input',21)+T(150,210,'120 V × 2 A',23)+T(410,164,'Secondary output',21)+T(410,210,'240 V × 1 A',23)+T(280,300,'240 W in = 240 W out',27)+T(280,355,'VpIp = VsIs',26)+T(280,410,'100% efficiency assumed · no energy created',18)+T(280,454,'Coil construction / turns ratio are later separate-Physics content',14);
return domesticSVG(body,state==='4'?'Ideal transformer: 120 V times 2 A equals 240 V times 1 A; both powers 240 W.':`Grid purpose schematic, not circuit connectivity. Sending ${P} W at ${V} V. ${revealed?'Current '+r.I+' A; total line resistance 1 ohm dissipates '+r.loss+' W, leaving '+r.received+' W.':'Predicted cable loss concealed until reveal.'} Transformer losses and real network regulation omitted. The two movie states are distinct steady comparisons.`);}
export function domesticFigure(o={}){if(o.concealed)return domesticSVG(T(280,230,'Predict, then reveal evidence',24),'Evidence concealed until prediction');let kind=(o.kind||'sources').replace(/-(model|data)$/,'');if(kind==='sources')return waveform(o);if(kind==='mains')return mainsFigure(o);if(kind==='grid')return gridFigure(o);return energyFigure({...o,kind});}
